import CustomNav from '../CustomsNav';
import { userData } from '../../helpers';
const  Home = () =>{

    const {username} = userData () ;
    return (
        <div>
            
            <CustomNav/>
            <div className='Home'>
                <h2>welcome{username}</h2>
            </div>
        </div>
    )
}
export default Home;
